from math import comb
def majority(p, n):                               # independent samples, binary right/wrong
    return sum(comb(n, k) * p**k * (1 - p)**(n - k) for k in range(n // 2 + 1, n + 1))
votes = {n: round(majority(0.6, n), 3) for n in (1, 5, 15)}

